# -*- coding: utf-8 -*-
"""MANAPRINT — RUBIS 90 · 14 boules · maquette Canva de Maeva (27/11/2026, « rubis90_canva_12_A4 »).
Reprise TELLE QUELLE : 12 cartons / feuille A4 PAYSAGE (3 x 4), traits de coupe en pointillés.
Chaque carton : RUBIS 90, le rubis et le diamant (dessins Canva posés en pochoir : en couleur,
MANAPRINT les repeint avec les cases, les chiffres restent noirs), les étoiles, la bande R U B I S,
14 cases (la case du centre de B reste vide), le N°.
RÈGLE (celle de RUBIS 90, inchangée) : R 1-18 x3 · U 19-36 x3 · B 37-54 x2 (haut et bas, centre vide) ·
   I 55-72 x3 · S 73-90 x3 — triés du plus petit en haut au plus grand en bas.   Crieur : 1 à 90.
Chiffres Times 30 pt noirs, comme sur la maquette.
Le tout est réduit pour garder 6 mm de marge d'impression (Konica / Sharp)."""

import io, random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4, landscape
from reportlab.lib import colors

try:
    from generators import canva_masque as _masque
except Exception:
    import canva_masque as _masque

PAGE_W, PAGE_H = landscape(A4)
COLS, RANGS = 3, 4
CARTES_PAGE = COLS * RANGS                # 12
CELL_W, CELL_H = 280.6299, 148.8189
NOIR = colors.black
POLICE_NUM = "Times-Roman"
TAILLE_NUM = 30
# (centre x, ligne de base) : colonne par colonne R U B I S, de haut en bas (B : haut et bas)
_XC = (34.299, 87.307, 140.315, 193.323, 246.331)
_YL = (75.827, 44.362, 12.898)
CASES = ([(_XC[0], y) for y in _YL] + [(_XC[1], y) for y in _YL] + [(_XC[2], _YL[0]), (_XC[2], _YL[2])]
         + [(_XC[3], y) for y in _YL] + [(_XC[4], y) for y in _YL])
# (x, y, largeur, hauteur, n° du dessin) : le rubis à gauche, le diamant à droite
_IMGS = [(35.71654, 117.0709, 23.9537, 24.37795, 0), (234.7087, 117.1146, 31.1811, 24.33421, 1)]

MARGE_SURE = 6 * 72 / 25.4
ECHELLE = min((PAGE_W - 2 * MARGE_SURE) / PAGE_W, (PAGE_H - 2 * MARGE_SURE) / PAGE_H)
DECAL_X = (PAGE_W - PAGE_W * ECHELLE) / 2.0
DECAL_Y = (PAGE_H - PAGE_H * ECHELLE) / 2.0
_DEJA = set()


def _numeros(rng):
    t = None
    for _ in range(500):
        t = tuple(sorted(rng.sample(range(1, 19), 3)) + sorted(rng.sample(range(19, 37), 3))
                  + sorted(rng.sample(range(37, 55), 2)) + sorted(rng.sample(range(55, 73), 3))
                  + sorted(rng.sample(range(73, 91), 3)))
        if t not in _DEJA:
            break
    _DEJA.add(t)
    return t


def _txt(c, s, x, y, police, taille, col, centre=False):
    w = c.stringWidth(s, police, taille)
    t = c.beginText(x - w / 2.0 if centre else x, y); t.setFont(police, taille)
    t.setFillColor(col); t.textOut(s)
    c.drawText(t)


def _en_teinte():
    import sys
    for nom in ("app", "__main__"):
        m = sys.modules.get(nom)
        e = getattr(m, "_TEINTE_ETAT", None) if m else None
        if e is not None and getattr(e, "canva", False):
            return True
    return False


def _modele(c):
    if getattr(c, "_rubis90_modele", False):
        return
    import base64
    d = _DESSIN
    teinte = _en_teinte()
    if teinte:          # version couleur : les cases grises prennent aussi la couleur du carton
        d = d.replace(".45 .45 .45 RG", "0 0 0 RG")
    for k, v in (("{HB}", "Helvetica-Bold"), ("{H}", "Helvetica")):
        d = d.replace(k, c._doc.getInternalFontName(v))
    c.beginForm("RUBIS90_CANVA", 0, 0, CELL_W, CELL_H)
    c._code.append("q\n0 g\n0 G")
    morceaux = d
    for i in range(len(_IMGS)):
        morceaux = morceaux.replace("@IMG%d@" % i, "\x00%d\x00" % i)
    for j, part in enumerate(morceaux.split("\x00")):
        if j % 2 == 1:
            i = int(part); x, y, w, h, k = _IMGS[i]
            _masque.poser(c, "RUBIS90_IMG_%d" % k, base64.b64decode(_PNG[k]), x, y, w, h)
        elif part:
            c._code.append(part)
    c._code.append("Q")
    c.endForm()
    c._rubis90_modele = True


def _billet(c, ox, oy, serie, nums, col):
    _modele(c)
    c.saveState()
    c.translate(ox, oy)
    c.doForm("RUBIS90_CANVA")
    _txt(c, "N\u00b0 %06d" % serie, 9.637795, 135.2126, "Helvetica-Bold", 5.2, colors.Color(.2, .2, .2))
    for (x, y), n in zip(CASES, nums):
        _txt(c, str(n), x, y, POLICE_NUM, TAILLE_NUM, col, centre=True)
    c.restoreState()


def generer_pdf(nb_cartes=None, nb_tickets=None, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", page_start=1, evenement_id="", style="", motif="", **_ig):
    n_ = nb_cartes if nb_cartes is not None else nb_tickets
    n_ = max(1, int(n_ if n_ else CARTES_PAGE))
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=(PAGE_W, PAGE_H), pageCompression=1)
    c.setTitle("RUBIS 90 · 14 boules")
    rng = random.Random(int(serie_start) * 100003 + 2723)
    _DEJA.clear()
    serie = int(serie_start)
    faits = 0
    try:
        no_page = max(1, int(page_start))
    except Exception:
        no_page = 1
    while faits < n_:
        c.setFillColor(colors.Color(0.5, 0.5, 0.5)); c.setFont("Helvetica", 7)
        c.drawRightString(PAGE_W - DECAL_X, PAGE_H - DECAL_Y / 2.0 - 2.5, "page %d" % no_page)
        entete = "  ·  ".join(t for t in ((nom_evenement or "").strip(), (date_lieu or "").strip()) if t)
        if entete:
            c.setFillColor(NOIR); c.setFont("Helvetica-Bold", 7)
            c.drawCentredString(PAGE_W / 2.0, PAGE_H - DECAL_Y / 2.0 - 2.5, entete)
        c.saveState()
        c.translate(DECAL_X, DECAL_Y); c.scale(ECHELLE, ECHELLE)
        for idx in range(CARTES_PAGE):
            if faits >= n_:
                break
            ox = (idx % COLS) * CELL_W
            oy = (RANGS - 1 - idx // COLS) * CELL_H
            _billet(c, ox, oy, serie, _numeros(rng), NOIR)
            serie += 1
            faits += 1
        c.setStrokeColor(colors.Color(0.5, 0.5, 0.5)); c.setLineWidth(0.3); c.setDash(2, 2)
        for i in range(1, COLS):
            c.line(i * CELL_W, 0, i * CELL_W, RANGS * CELL_H)
        for j in range(1, RANGS):
            c.line(0, j * CELL_H, COLS * CELL_W, j * CELL_H)
        c.restoreState()
        c.showPage()
        no_page += 1
    c.save()
    buf.seek(0)
    return buf


